  "items": [
    {
      "title": "GERDA: German Election Database – State Election Results (1946–2026)",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "One of the most comprehensive datasets for historical German elections. Contains state parliamentary election (Landtagswahl) results at municipality and constituency levels, including elections during the 1990s in Berlin, Baden-Württemberg, Bavaria, Bremen, Hesse, Hamburg, Lower Saxony, North Rhine-Westphalia, Rhineland-Palatinate, Saarland, and Schleswig-Holstein. Includes party vote shares and downloadable CSV, Excel, and RDS files."
    },
    {
      "title": "GERDA: The German Election Database – Scientific Data Publication",
      "url_or_doi": "https://doi.org/10.1038/s41597-025-04811-5",
      "justification": "Peer-reviewed publication describing the construction, coverage, and validation of GERDA. Particularly useful for researchers studying German state and local elections during the 1990s. Documents historical election results, geographical harmonization, and data sources across German federal states."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Historical Election Results in German Federal States Since 1946",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides separate historical election datasets for all 11 requested German federal states. Includes election results from the 1990s, political party vote shares, parliamentary seat distributions, and representative electoral statistics such as turnout and voting behavior by age and gender where available. Particularly useful for comparing electoral developments across states."
    },
    {
      "title": "GESIS – German State Election Studies (Landtagswahlen)",
      "url_or_doi": "https://www.gesis.org/en/elections/german-state-elections",
      "justification": "GESIS maintains an extensive collection of German state election studies dating back to 1962. The collection includes election-related surveys for individual federal states, including studies conducted during the 1990s. Useful for investigating voter preferences, political attitudes, party identification, and electoral behavior rather than just official election results."
    },
    {
      "title": "Federal Returning Officer – Historical German State Parliamentary Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/dam/jcr/a333e523-0717-42ad-a772-d5ad7e7e97cc/ltw_erg_gesamt.pdf",
      "justification": "Official compilation of historical state parliamentary election results published by Germany's Federal Returning Officer. Includes election results from the 1990s across the requested federal states, with information about votes, party performance, turnout, and parliamentary seats. Particularly valuable as an authoritative reference for validating other electoral datasets."
    },
    {
      "title": "GERDA – Harmonized State Election Results at Municipality Level (1990–2026)",
      "url_or_doi": "https://github.com/awiedem/german_election_data",
      "justification": "Provides harmonized municipality-level electoral data covering German state elections from 1990 onward. The state_harm_21 dataset standardizes historical results to 2021 administrative boundaries, making it especially useful for longitudinal comparisons across the requested states during the 1990s. Includes downloadable election data and documentation."
    },
    {
      "title": "GERDA – German Federal Election Results at Municipality Level (1990–2025)",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Contains federal parliamentary election results for 1990, 1994, and 1998, including municipality-level voting patterns across all 11 requested states. Provides party vote shares and geographically harmonized results. Particularly useful when the research question includes Bundestag elections held within these states, in addition to state parliamentary elections."
    },
    {
      "title": "GERDA – Historical State Parliamentary Election Constituency Results (1980–2026)",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "The ltw_wkr_unharm and ltw_wkr_unharm_long datasets provide state election results at electoral constituency (Wahlkreis) level, with coverage beginning in 1980. They include first- and second-vote results where applicable, organized by political party and constituency. Relevant for analyzing geographical voting differences in the requested German states during the 1990s, subject to historical constituency-level availability."
    },
    {
      "title": "GESIS – Integrated Historical German State Election Survey Collection",
      "url_or_doi": "https://www.gesis.org/en/elections/german-state-elections",
      "justification": "Provides access to historical election survey studies and integrated research resources covering German state elections, including the 1990s. Useful for comparing individual-level political attitudes and voting behavior across elections and federal states. The collection complements official election-result datasets by providing survey-based evidence."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Baden-Württemberg Historical Election Data (Since 1946)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Includes historical election results for Baden-Württemberg, covering the 1992 and 1996 state parliamentary elections. Provides political party results and historical electoral statistics suitable for examining electoral changes during the 1990s."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Bavaria Historical Election Data (Since 1946)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical election results for Bavaria, including the 1990, 1994, and 1998 state parliamentary elections. Useful for analyzing CSU electoral dominance, opposition party performance, voting trends, and parliamentary representation throughout the decade."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Berlin Historical Election Data (Since 1946)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Contains historical election statistics for Berlin, including the 1990, 1995, and 1999 elections to the Berlin House of Representatives. Particularly relevant for studying electoral patterns following German reunification and political differences between eastern and western Berlin."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Bremen Historical Election Data (Since 1946)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical election results for Bremen, including the 1991, 1995, and 1999 Bürgerschaft elections. Useful for studying party competition, electoral turnout, and changes in political representation during the 1990s."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Hesse Historical Election Data (Since 1946)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical election data for Hesse, including the 1991, 1995, and 1999 state parliamentary elections. Supports analysis of political party vote shares, changing electoral coalitions, and parliamentary seat distributions."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Hamburg Historical Election Data (Since 1946)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Contains historical election results for Hamburg, including the 1991, 1993, and 1997 Bürgerschaft elections. Useful for examining electoral competition, voter turnout, and changes in party representation during the 1990s."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Lower Saxony Historical Election Data (Since 1947)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical election results for Lower Saxony, including the 1990, 1994, and 1998 state parliamentary elections. Useful for investigating SPD and CDU electoral competition, political party performance, and historical voting trends."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – North Rhine-Westphalia Historical Election Data (Since 1947)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Includes historical election results for North Rhine-Westphalia, covering the 1990 and 1995 state parliamentary elections. Provides information on political party performance and parliamentary representation in Germany's most populous federal state."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Rhineland-Palatinate Historical Election Data (Since 1947)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Contains historical election statistics for Rhineland-Palatinate, including the 1991 and 1996 state parliamentary elections. Useful for analyzing changes in party support, electoral competition, and coalition politics during the 1990s."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Saarland Historical Election Data (Since 1947)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical election results for Saarland, including the 1990, 1994, and 1999 state parliamentary elections. Relevant for examining SPD and CDU competition, voting patterns, and parliamentary representation during the decade."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Schleswig-Holstein Historical Election Data (Since 1947)",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Contains historical election results for Schleswig-Holstein, including the 1992 and 1996 state parliamentary elections. Useful for studying party vote shares, changes in electoral support, and parliamentary seat distributions during the 1990s."
    },
    {
      "title": "GERDA – Historical German Municipal Election Results (1969–2026)",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Provides municipality-level election results and political party vote shares for local elections across Germany, including elections held during the 1990s. Relevant for researchers interested in municipal rather than state parliamentary elections in the requested federal states. Historical geographic coverage varies by state; Schleswig-Holstein has particularly limited municipal coverage before 2018."
    },
    {
      "title": "GERDA – Historical German County Council Election Results (1948–2026)",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Includes historical county council (Kreistag) election results at municipality and county levels. The county_elec_unharm dataset covers elections beginning in 1948, while harmonized datasets support comparisons from the 1990s onward. Useful for examining local electoral patterns and political party support across counties in the requested states."
    }
  ]
}
